import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.D5wUhsuj.js";const k=JSON.parse('{"title":"PhyAgentOS Operations Manual","description":"","frontmatter":{},"headers":[],"relativePath":"user_manual/README_en.md","filePath":"user_manual/README_en.md"}'),n={name:"user_manual/README_en.md"};function l(o,e,r,d,c,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="phyagentos-operations-manual" tabindex="-1">PhyAgentOS Operations Manual <a class="header-anchor" href="#phyagentos-operations-manual" aria-label="Permalink to &quot;PhyAgentOS Operations Manual&quot;">​</a></h1><p><a href="/docs/user_manual/README">中文</a> · <a href="/docs/en/">Documentation index</a></p><blockquote><p>Version: 1.0.0</p></blockquote><h2 id="_1-runtime-model" tabindex="-1">1. Runtime model <a class="header-anchor" href="#_1-runtime-model" aria-label="Permalink to &quot;1. Runtime model&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User/Channel → AgentLoop → Forge task and Tool API tools</span></span>
<span class="line"><span>                                  │</span></span>
<span class="line"><span>                   bound call or diagnostic Query</span></span>
<span class="line"><span>                                  ▼</span></span>
<span class="line"><span>                         ForgeToolClient</span></span>
<span class="line"><span>                                  ▼</span></span>
<span class="line"><span>Gateway /tools → ToolInvocation → ToolEndpoint → Dora → robot/simulator</span></span>
<span class="line"><span></span></span>
<span class="line"><span>bound calls → immutable Skill binding → AgentTask SQLite → verification/experience</span></span></code></pre></div><p>Gateway owns execution. PAOS owns user-task aggregation and semantic verdicts. Skill Runtime owns the explicit lifecycle of installed Bundle profiles; it does not replace Gateway execution truth.</p><h2 id="_2-pre-deployment-checks" tabindex="-1">2. Pre-deployment checks <a class="header-anchor" href="#_2-pre-deployment-checks" aria-label="Permalink to &quot;2. Pre-deployment checks&quot;">​</a></h2><h3 id="paos-host" tabindex="-1">PAOS host <a class="header-anchor" href="#paos-host" aria-label="Permalink to &quot;PAOS host&quot;">​</a></h3><ul><li>Python 3.11 or 3.12 and the intended v1.0.0 environment are installed.</li><li><code>paos status</code> resolves the expected config, workspace, model, and provider.</li><li>Workspace, PAOS data paths, and artifact paths have sufficient permissions and disk space.</li><li>Verification provider credentials are available when non-<code>off</code> tasks are allowed.</li></ul><h3 id="skill-runtime" tabindex="-1">Skill Runtime <a class="header-anchor" href="#skill-runtime" aria-label="Permalink to &quot;Skill Runtime&quot;">​</a></h3><ul><li>Skill Bundle metadata includes size and SHA-256; every Node lock has an exact SHA-256 and resolves to a sized direct download.</li><li>Required binaries are executable, required assets exist, and required environment variables are set.</li><li>Dora CLI v0.4.1 with <code>dora-message</code> v0.7.0, the current Forge Skill compatibility baseline, is installed and on <code>PATH</code>; <code>dora --version</code> reports both expected versions. Installation is documented in the <a href="/docs/en/02-user-manual#dora-cli-for-managed-skill-profiles">user manual</a>.</li><li>The profile Gateway address is not occupied by an unmanaged process.</li></ul><h3 id="forge-gateway" tabindex="-1">Forge Gateway <a class="header-anchor" href="#forge-gateway" aria-label="Permalink to &quot;Forge Gateway&quot;">​</a></h3><ul><li><code>GET /tools</code> returns a successful object envelope.</li><li>Required ToolSpecs and <code>/tools/{tool_id}/context</code> are present and ready.</li><li>Endpoint operation <code>max_concurrency</code> matches the robot&#39;s safe concurrency.</li><li>ToolSpec semantics, schemas, bindings, and readiness match the installed Skill manifest.</li></ul><h3 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h3><ul><li><code>.paos/agent_tasks</code>, <code>.paos/evolution</code>, Agent conversation history, and Skill Runtime state are on durable storage.</li><li>Backup and retention procedures do not delete evolution data when rotating robot evidence.</li></ul><h2 id="_3-startup-and-health" tabindex="-1">3. Startup and health <a class="header-anchor" href="#_3-startup-and-health" aria-label="Permalink to &quot;3. Startup and health&quot;">​</a></h2><p>For a managed Skill profile:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">profil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">other-skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">profil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or: paos gateway</span></span></code></pre></div><p><code>paos skill start</code> runs <code>dora check</code> and invokes <code>dora up</code> if the local coordinator and daemon are not ready; operators do not need to start them separately. After startup, <code>dora check</code> should succeed.</p><p>Healthy Runtime status requires persisted <code>running</code>, a live named Dora flow, Gateway <code>/tools</code>, and ready context for every manifest <code>required_tool</code>. Use <code>paos skill logs &lt;name&gt;</code> for lifecycle and Dora launch logs. Runtime switching is permitted only with no non-terminal AgentTask; the target must become ready before selection, and a failed same-Gateway switch restores the previous Runtime. Long-running Agents follow the persisted selection before the next activation or Tool call.</p><p>The Agent uses only the Gateway identity and URL of this managed active Runtime. <code>paos status</code> checks local configuration only; use <code>forge_tool_context</code> for live Tool readiness.</p><h2 id="_4-task-monitoring" tabindex="-1">4. Task monitoring <a class="header-anchor" href="#_4-task-monitoring" aria-label="Permalink to &quot;4. Task monitoring&quot;">​</a></h2><p>Record these identities separately:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Identity</th><th style="text-align:left;">Owner</th><th style="text-align:left;">Use</th></tr></thead><tbody><tr><td style="text-align:left;"><code>task_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">User-visible aggregate and verification</td></tr><tr><td style="text-align:left;"><code>binding_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Frozen Skill version, Runtime, and ToolSpec set</td></tr><tr><td style="text-align:left;"><code>revision_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Append-only planning generation</td></tr><tr><td style="text-align:left;"><code>record_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">One bound Query, Action, or Session record</td></tr><tr><td style="text-align:left;"><code>caller_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">Persisted before asynchronous admission</td></tr><tr><td style="text-align:left;"><code>invocation_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">One asynchronous Action or Session lifecycle</td></tr><tr><td style="text-align:left;"><code>attempt_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">One execution attempt</td></tr></tbody></table><p>Use <code>forge_task_get(task_id)</code> for aggregate state and Tool records. Use the task-bound Action or Session status/result tools for execution truth. A result endpoint may return HTTP 202 while pending.</p><p>Expected task states:</p><table tabindex="0"><thead><tr><th style="text-align:left;">State</th><th style="text-align:left;">Operator meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>executing</code></td><td style="text-align:left;">Planning or bound Tool calls continue.</td></tr><tr><td style="text-align:left;"><code>cancelling</code></td><td style="text-align:left;">Cancellation was requested; physical stop is not yet proven.</td></tr><tr><td style="text-align:left;"><code>awaiting_replan</code></td><td style="text-align:left;">Verification permits a bounded new PlanRevision before its deadline.</td></tr><tr><td style="text-align:left;"><code>succeeded</code> / <code>failed</code> / <code>cancelled</code></td><td style="text-align:left;">PAOS aggregate is terminal. Inspect invocation facts separately when needed.</td></tr></tbody></table><h2 id="_5-cancellation-and-stop" tabindex="-1">5. Cancellation and stop <a class="header-anchor" href="#_5-cancellation-and-stop" aria-label="Permalink to &quot;5. Cancellation and stop&quot;">​</a></h2><p>For one Action, call <code>forge_tool_cancel_action(task_id, invocation_id)</code>, then continue status/result reconciliation. For all Actions bound to a task, call <code>forge_task_cancel(task_id, reason)</code>, reconcile each invocation, and inspect physical state when effects are uncertain. Task cancellation also stops task-owned Sessions; shared and runtime-owned Sessions retain their independent lifecycle.</p><p>Never report <code>requested</code>, <code>accepted</code>, a timeout, or <code>unknown</code> as proof of physical stop. Do not retry the motion until effect reconciliation is complete.</p><p>Stop a managed Runtime only after tracked invocations and Sessions are terminal and no task binding remains:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>--force</code> is reserved for an operator who has independently assessed the physical system. Before stopping the managed Dora flow it makes best-effort cancel/stop requests for tracked Actions and Sessions, then records each request and unresolved reference in the Runtime audit. Acceptance does not prove termination and Gateway invocation results are not rewritten.</p><h2 id="_6-graceful-shutdown" tabindex="-1">6. Graceful shutdown <a class="header-anchor" href="#_6-graceful-shutdown" aria-label="Permalink to &quot;6. Graceful shutdown&quot;">​</a></h2><ol><li>Stop admitting new user tasks.</li><li>Read the active AgentTask and reconcile every Action/Session invocation.</li><li>Finalize or cancel/finalize the AgentTask.</li><li>Stop PAOS channels or Agent.</li><li>Stop the Skill Runtime profile.</li><li>Stop shared infrastructure only if no other profile uses it.</li></ol><h2 id="_7-crash-restart" tabindex="-1">7. Crash restart <a class="header-anchor" href="#_7-crash-restart" aria-label="Permalink to &quot;7. Crash restart&quot;">​</a></h2><p>After a PAOS restart, open the persisted AgentTask with its known <code>task_id</code>. Do not recreate or resubmit an Action or Session from local intent. Query every persisted <code>invocation_id</code> and update the record from Gateway status/result. If Gateway can no longer resolve an invocation, treat the effect as unknown and escalate to physical-state inspection.</p><p><code>paos skill status &lt;name&gt;</code> reconciles Runtime state against Dora and Gateway health. It can move a persisted starting/running state to failed when the flow or Tool contexts are unavailable; restart only after diagnosing the previous flow.</p><h2 id="_8-backup-and-disk-management" tabindex="-1">8. Backup and disk management <a class="header-anchor" href="#_8-backup-and-disk-management" aria-label="Permalink to &quot;8. Backup and disk management&quot;">​</a></h2><p>With PAOS stopped, back up the database together with WAL/SHM files and the referenced trees:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/.paos/agent_tasks/tasks.sqlite3*</span></span>
<span class="line"><span>&lt;workspace&gt;/.paos/evolution/experience.sqlite3*</span></span>
<span class="line"><span>&lt;workspace&gt;/.paos/evolution/revisions/</span></span>
<span class="line"><span>&lt;workspace&gt;/artifacts/agent_tasks/</span></span>
<span class="line"><span>&lt;workspace&gt;/skills/</span></span></code></pre></div><p>Also retain installed Bundle/Node manifests, Runtime state, and lifecycle logs according to the deployment&#39;s PAOS data-path policy. Evidence retention may prune entity files after verification; it must not remove task records, invocation references, or evolution history.</p><h2 id="_9-failure-layers" tabindex="-1">9. Failure layers <a class="header-anchor" href="#_9-failure-layers" aria-label="Permalink to &quot;9. Failure layers&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Typical symptom</th><th style="text-align:left;">First action</th></tr></thead><tbody><tr><td style="text-align:left;">Registry/install</td><td style="text-align:left;">Digest, size, manifest, or lock failure</td><td style="text-align:left;">Correct the signed metadata or artifact; do not bypass validation.</td></tr><tr><td style="text-align:left;">Runtime</td><td style="text-align:left;">Dora flow or Gateway health unavailable</td><td style="text-align:left;">Inspect <code>paos skill status</code> and <code>logs</code>.</td></tr><tr><td style="text-align:left;">Tool context</td><td style="text-align:left;">Tool missing, unbound, or not ready</td><td style="text-align:left;">Inspect ToolSpec, Endpoint, frame, and required profile.</td></tr><tr><td style="text-align:left;">Admission</td><td style="text-align:left;">HTTP/contract failure</td><td style="text-align:left;">Preserve any returned invocation ID; determine whether Gateway accepted work.</td></tr><tr><td style="text-align:left;">Execution</td><td style="text-align:left;">pending, failed, cancelled, or unknown</td><td style="text-align:left;">Reconcile using the same invocation ID and inspect physical state when uncertain.</td></tr><tr><td style="text-align:left;">Evidence</td><td style="text-align:left;">before/after source missing</td><td style="text-align:left;">Inspect source readiness and bundle errors; keep ToolResult authoritative.</td></tr><tr><td style="text-align:left;">Verification</td><td style="text-align:left;">invalid/inconclusive/service error</td><td style="text-align:left;">Inspect task contract, evidence, provider, and mode semantics.</td></tr><tr><td style="text-align:left;">Evolution</td><td style="text-align:left;">reflection or promotion blocked</td><td style="text-align:left;">Inspect evolution events; execution remains unaffected.</td></tr></tbody></table><h2 id="_10-operational-acceptance-checklist" tabindex="-1">10. Operational acceptance checklist <a class="header-anchor" href="#_10-operational-acceptance-checklist" aria-label="Permalink to &quot;10. Operational acceptance checklist&quot;">​</a></h2><ul><li>[ ] Package and runtime version report 1.0.0.</li><li>[ ] General Agent tools and dynamic MCP tools remain registered.</li><li>[ ] Required Skill Bundle and all node artifacts verify.</li><li>[ ] Managed Runtime reaches ready and all Tool contexts are healthy.</li><li>[ ] Diagnostic Query and bound Query/Action/Session use the same Gateway Tool API.</li><li>[ ] Action/Session admission, pending, terminal, cancel/stop, timeout, ownership, and unknown behavior are exercised.</li><li>[ ] One-active-AgentTask enforcement and PlanRevision recovery are exercised.</li><li>[ ] Evidence and task-level verification complete for a bound workflow.</li><li>[ ] Experience records AgentTask, Skill activation, verification, and invocation references.</li><li>[ ] Backups include AgentTask and evolution persistence.</li><li>[ ] Concrete Skill/hardware acceptance is recorded separately with exact assets, nodes, and environment.</li></ul><h2 id="next-reading" tabindex="-1">Next reading <a class="header-anchor" href="#next-reading" aria-label="Permalink to &quot;Next reading&quot;">​</a></h2><ul><li><a href="/docs/en/02-user-manual">User Manual</a></li><li><a href="/docs/user_development_guide/COMMUNICATION_en">Communication Architecture</a></li><li><a href="/docs/forge/README">Forge Tool API Contract</a></li></ul>`,48)])])}const u=t(n,[["render",l]]);export{k as __pageData,u as default};
